size_t fn_06(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {
    if (out_cap < len) return -1;
    uint8_t s[256];
    uint8_t k[8];
    for (int i = 0; i < 8; i++) k[i] = (arg >> (i * 8)) & 0xff;
    for (int i = 0; i < 256; i++) s[i] = i;
    for (int i = 0, j = 0; i < 256; i++) {
        j = (j + s[i] + k[i % 8]) & 0xff;
        uint8_t t = s[i];
        s[i] = s[j];
        s[j] = t;
    }
    for (int i = 0, j = 0, n = 0; n < len; n++) {
        i = (i + 1) & 0xff;
        j = (j + s[i]) & 0xff;
        uint8_t t = s[i];
        s[i] = s[j];
        s[j] = t;
        out[n] = in[n] ^ s[(s[i] + s[j]) & 0xff];
    }
    return len;
}
